import os,re
ROOT=r"D:/repository"
PRUNE={"node_modules",".git","dist","build",".idea",".vscode","unpackage","coverage","skills","memory-migration-archive","openviking-data"}
EXTS=(".vue",".js",".ts",".jsx",".tsx",".cjs",".mjs",".json",".scss",".css")

def allfiles():
    for dp,dns,fns in os.walk(ROOT):
        dns[:]=[d for d in dns if d not in PRUNE]
        for fn in fns:
            if fn.endswith(EXTS):
                yield os.path.join(dp,fn)

# filename substring checks
FNAMES={
 "16_auth-helpers.js":"auth-helpers",
 "31_e2e-flood-lib.cjs":"e2e-flood-lib",
 "33_operatingAssets.vue":"operatingassets",
 "20_find-unused-api.cjs":"find-unused-api",
 "3_verify.vue":"verify.vue",
 "3_verification.vue":"verification.vue",
 "10_zs-file-upload.vue":"zs-file-upload",
}
fnres={k:[] for k in FNAMES}
# in-file token checks: (label, filename-substr, token)
INFILE=[
 ("18_verifyInfo_in_FormManual","formmanual","verifyinfo"),
 ("23_WUXI_SVG_in_map","mapoverview","wuxi_svg_group_regions"),
 ("15_grid_bottom_in_assetPanorama","assetpanorama","bottom"),
 ("10_isShowTip_in_zsfileupload","zs-file-upload","isshowtip"),
]
ifres={k[0]:[] for k in INFILE}

for f in allfiles():
    base=os.path.basename(f).lower()
    rel=f.replace(ROOT+os.sep,"")
    for k,sub in FNAMES.items():
        if len(fnres[k])<5 and sub.lower() in base:
            fnres[k].append(rel)
    matched_infile=[lab for lab,fsub,tok in INFILE if fsub in base]
    if matched_infile:
        try: t=open(f,encoding="utf-8",errors="ignore").read()
        except: continue
        for lab,fsub,tok in INFILE:
            if lab in matched_infile and tok in t.lower() and len(ifres[lab])<5:
                ifres[lab].append(rel)

out=["== FILENAME existence (real code only) =="]
for k,h in fnres.items():
    out.append(f"{k}: {len(h)} "+(" | ".join(h) if h else "NONE"))
out.append("== IN-FILE token ==")
for k,h in ifres.items():
    out.append(f"{k}: {len(h)} "+(" | ".join(h) if h else "NONE"))
open(r"C:/Users/Administrator/.dsh/cache/memory-audit/focus.txt","w",encoding="utf-8").write("\n".join(out))
print("done")

